// Custom service worker additions — merged into the Workbox-generated sw.js
// by @ducanh2912/next-pwa (customWorkerSrc). Adds Web Push support, which
// replaces the old Telegram bot for proactive notifications (digest, scout
// results, follow-up nudges). Everything else (caching, offline) stays
// entirely generated by next-pwa; this file only adds these two listeners.

type PushPayload = { title: string; body: string; url?: string };

self.addEventListener("push", (event: PushEvent) => {
  let payload: PushPayload = { title: "Career Scout", body: "" };
  try {
    if (event.data) payload = event.data.json();
  } catch {
    if (event.data) payload.body = event.data.text();
  }

  event.waitUntil(
    self.registration.showNotification(payload.title || "Career Scout", {
      body: payload.body || "",
      icon: "/icon-192.png",
      badge: "/icon-192.png",
      data: { url: payload.url || "/dashboard" },
    })
  );
});

self.addEventListener("notificationclick", (event: NotificationEvent) => {
  event.notification.close();
  const url = (event.notification.data?.url as string) || "/dashboard";

  event.waitUntil(
    (async () => {
      const allClients = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      const existing = allClients.find((c) => new URL(c.url).pathname === url);
      if (existing) {
        await (existing as WindowClient).focus();
      } else {
        await self.clients.openWindow(url);
      }
    })()
  );
});
